def validate(dev, data):
    missing = [f for f in ("mgmt_ip", "site", "device_type") if not data.get(f)]
    if missing:
        raise ValueError(f"{dev}: 台账缺字段 {missing}")   # 先验数据再渲染，模板不背数据的锅

{# templates/interface.j2 —— 平台差异集中在模板层的条件片段（卡 W3 纪律） #}
{% if platform == 'cisco_ios' %}
interface {{ iface.name }}
 description {{ iface.description }}
{% if iface.mgmt_only %}
 ip address {{ iface.ip4.address | ipaddr('address') }} {{ iface.ip4.address | ipaddr('netmask') }}
{% else %}
 switchport mode access
 switchport access vlan {{ iface.untagged_vlan.vid }}
{% endif %}
{% elif platform == 'huawei_vrp' %}
interface {{ iface.name | huawei_ifname }}
 description {{ iface.description }}
{% if iface.mgmt_only %}
 ip address {{ iface.ip4.address | ipaddr('address') }} {{ iface.ip4.address | ipaddr('netmask') }}
{% else %}
 port link-type access
 port default vlan {{ iface.untagged_vlan.vid }}
{% endif %}
{% endif %}

// Jenkinsfile
pipeline {
  agent any
  stages {
    stage('check') {
      steps { sh 'ansible-playbook deploy.yml --check --diff' }
    }
    stage('approval') {
      steps {
        input message: '确认下发到 HQ 域？', ok: 'APPROVE',
              submitter: 'netops-approvers'
      }
    }
    stage('deploy') {
      steps {
        withCredentials([sshUserPrivateKey(credentialsId: 'netops-ssh',
                          keyFileVariable: 'KEY')]) {
          sh 'ansible-playbook deploy.yml -i hosts -f 20'
        }
      }
    }
    stage('verify') {
      steps { sh '/opt/netops/bin/read-back-verify.sh' }
    }
  }
  post {
    failure { mail to: 'netops@corp.example', subject: "deploy failed #${env.BUILD_NUMBER}" }
  }
}

terraform {
  required_version = ">= 1.6.0"     # 低于此版本直接报错拒跑
  # 语义约束符：>=、<=、!=、~>（悲观约束）
  #   ~> 1.6  意为 >=1.6, <2.0（次版本级）
  #   ~> 1.6.2 意为 >=1.6.2, <1.7.0（补丁级）
}

# versions.tf
terraform {
  required_version = ">= 1.6.0"
  required_providers {
    alicloud = {
      source  = "aliyun/alicloud"
      version = "~> 1.240"
    }
  }
}

variable "vpc_cidr" {
  type        = string
  description = "HQ VPC 网段"
  default     = "10.0.0.0/16"

  validation {                          # 渲染前校验（Terraform 0.13+）
    condition     = can(cidrnetmask(var.vpc_cidr))
    error_message = "vpc_cidr 必须是合法 CIDR，如 10.0.0.0/16。"
  }
}

variable "instance_count" {
  type    = number
  default = 2
  validation {
    condition     = var.instance_count >= 1 && var.instance_count <= 10
    error_message = "instance_count 必须在 1–10 之间。"
  }
}

variable "subnet_cidrs" {
  type = list(string)                   # 集合类型
}

variable "db_password" {
  type      = string
  sensitive = true                       # CLI 输出与日志里隐藏（State 仍明文，见 4.18）
}

locals {
  name_prefix = "${var.project}-${var.env}"             # 组合命名
  common_tags = {                                       # 统一标签（多云都在用 tags 的地方）
    Project   = var.project
    Env       = var.env
    ManagedBy = "terraform"      # 良好实践：标记资源由 Terraform 管理（import/排查时一眼分清）
  }
}

output "vpc_id" {
  description = "HQ VPC ID，供其他模块/项目引用"
  value       = alicloud_vpc.main.id
}
output "db_password" {
  value     = var.db_password
  sensitive = true          # terraform output 会打 *** ；要真值需 -raw
}

variable "env" { type = string }
variable "zones" {
  type    = list(string)
  default = ["cn-hangzhou-a", "cn-hangzhou-b"]
}
locals {
  prefix = "${var.project}-${var.env}"
}
output "zone_count" {
  value = length(var.zones)
}
resource "alicloud_vswitch" "web" {
  count      = length(var.zones)                        # 每可用区一个交换机（4.13 详解）
  vswitch_name = "${local.prefix}-web-${format("%02d", count.index + 1)}"
  vpc_id     = alicloud_vpc.main.id
  cidr_block = cidrsubnet(var.vpc_cidr, 8, count.index)  # cidrsubnet 函数：/16 → /24 逐区切分
  zone_id    = var.zones[count.index]
}

terraform {
  required_version = ">= 1.6.0"
  required_providers {
    alicloud = {
      source  = "aliyun/alicloud"      # registry 地址：命名空间/名字
      version = "~> 1.240"             # 悲观约束，升级前人工评审
    }
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "alicloud" { region = "cn-hangzhou" }                       # 默认实例
provider "alicloud" {
  alias        = "shanghai"
  region       = "cn-shanghai"
  access_key   = var.shanghai_ak      # 多账号时在此区分凭据（凭据本身走 env/密管，见 4.18）
  secret_key   = var.shanghai_sk
}
resource "alicloud_vswitch" "sh_web" {
  provider = alicloud.shanghai       # 资源级绑定：这个资源由上海实例操作
  ...
}
# data 源同理：data "alicloud_zones" "sh" { provider = alicloud.shanghai ... }

# 文件位置：Windows %APPDATA%\terraform.rc；Linux/macOS ~/.terraformrc
# 可用环境变量 TF_CLI_CONFIG_FILE 指向自定义位置（CI 里常用）
provider_installation {
  network_mirror {
    url = "https://mirrors.aliyun.com/terraform/"   # 阿里云官方提供的 Terraform 镜像
  }
  direct {
    exclude = []                                    # 未匹配的一律走直连 registry 兜底
  }
}

# —— 阿里云（aliyun/alicloud）——
provider "alicloud" { region = var.region }
resource "alicloud_vpc" "main" {
  vpc_name   = "${local.prefix}-vpc"
  cidr_block = var.vpc_cidr
}
resource "alicloud_security_group" "web" {
  name   = "${local.prefix}-sg-web"
  vpc_id = alicloud_vpc.main.id
}
resource "alicloud_security_group_rule" "allow_https" {
  type              = "ingress"
  ip_protocol       = "tcp"
  port_range        = "443/443"
  security_group_id = alicloud_security_group.web.id
  cidr_ip           = "0.0.0.0/0"
}

# —— AWS（hashicorp/aws）——
provider "aws" { region = var.aws_region }
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags                 = local.common_tags
}
resource "aws_security_group" "web" {
  name   = "${local.prefix}-sg-web"
  vpc_id = aws_vpc.main.id
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# —— 腾讯云（tencentcloudstack/tencentcloud）——
provider "tencentcloud" { region = var.tencent_region }
resource "tencentcloud_vpc" "main" {
  name       = "${local.prefix}-vpc"
  cidr_block = var.vpc_cidr
}
resource "tencentcloud_security_group" "web" {
  name        = "${local.prefix}-sg-web"
  description = "managed by terraform"
}

# providers.tf —— 生产（默认）+ 逃生（alias）双实例
provider "alicloud" {
  region = var.region
}                                     # 凭据走环境变量 ALICLOUD_ACCESS_KEY/ALICLOUD_SECRET_KEY

provider "alicloud" {
  alias      = "dr"
  region     = "cn-shanghai"
  access_key = var.dr_ak              # 灾备账号独立凭据（密管下发）
  secret_key = var.dr_sk
}

resource "alicloud_vpc" "main" { cidr_block = var.vpc_cidr }
resource "alicloud_vswitch" "web" {
  vpc_id = alicloud_vpc.main.id          # ← 引用即依赖：Terraform 保证 VPC 先创建完成
  cidr_block = cidrsubnet(var.vpc_cidr, 8, 1)
  zone_id    = var.zone_a
}
resource "alicloud_instance" "web1" {
  vswitch_id    = alicloud_vswitch.web.id   # ← 子网先就绪
  security_groups = [alicloud_security_group.web.id]
  instance_type = var.instance_type
  image_id      = data.alicloud_images.alios.id   # data 源（4.14）
}

resource "alicloud_dns_record" "web" {
  depends_on = [alicloud_instance.web1]   # 无引用关系，纯顺序约束
  ...
}

resource "alicloud_instance" "db" {
  ...
  lifecycle {
    prevent_destroy = true          # 永不销毁：有人手滑 destroy 时直接报错拦截
    ignore_changes  = [image_id]    # 忽略字段漂移：镜像升级走打镜像流程，不走 Terraform
    # create_before_destroy = true  # 见下文
  }
}

# 云盘与挂载（依赖链清晰：disk → attachment → instance 已存在）
resource "alicloud_disk" "db_data" {
  zone_id  = var.zone_a
  category = "cloud_essd"
  size     = 100
}
resource "alicloud_disk_attachment" "db_data" {
  disk_id     = alicloud_disk.db_data.id
  instance_id = alicloud_instance.db.id
}

resource "alicloud_vswitch" "web" {
  for_each     = toset(var.zones)
  vpc_id       = alicloud_vpc.main.id
  zone_id      = each.key
  cidr_block   = cidrsubnet(var.vpc_cidr, 8, index(var.zones, each.key))
  vswitch_name = "${local.prefix}-web-${each.key}"
}
resource "alicloud_instance" "web" {
  for_each        = toset(var.zones)
  vswitch_id      = alicloud_vswitch.web[each.key].id
  instance_type   = var.instance_type
  image_id        = data.alicloud_images.alios.id
  security_groups = [alicloud_security_group.web.id]
  instance_name   = "${local.prefix}-web-${each.key}"
  tags            = merge(local.common_tags, { Role = "web" })
  lifecycle {
    ignore_changes = [image_id]        # 镜像版本由打镜像流水线管理
  }
}

# 阿里云：查最新公共 Aliyun Linux 镜像
data "alicloud_images" "alios" {
  name_regex  = "^aliyun_3_x64"     # 正则筛选镜像名
  owners      = "system"            # 只查官方系统镜像，避免撞自定义镜像
  most_recent = true                # 多个命中取最新
}
resource "alicloud_instance" "web" { image_id = data.alicloud_images.alios.images[0].id ... }

# AWS：查最新 Ubuntu 22.04 AMI（099720109477 是 Canonical 官方账号 ID）
data "aws_ami" "ubuntu" {
  most_recent = true
  owners      = ["099720109477"]
  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-jammy-22.04-amd64-server-*"]
  }
}
resource "aws_instance" "web" { ami = data.aws_ami.ubuntu.id ... }

# 腾讯云：查公共镜像
data "tencentcloud_images" "tos" {
  image_type       = "PUBLIC_IMAGE"
  image_name_regex = "TencentOS Server 3"
}

# 阿里云：过滤出支持创建交换机的可用区
data "alicloud_zones" "all" {
  available_resource_creation = "VSwitch"
}
locals {
  usable_zones = data.alicloud_zones.all.zones     # list(string)
}

# AWS
data "aws_availability_zones" "all" { state = "available" }
locals { usable_zones = data.aws_availability_zones.all.names }

# 本项目要在老 VPC 里加交换机；VPC 本身由另一个项目的 Terraform 管
data "alicloud_vpcs" "existing" {
  name_regex = "^hq-prod-vpc$"
}
data "alicloud_vswitches" "in_vpc" {
  vpc_id = data.alicloud_vpcs.existing.vpcs[0].id
}
resource "alicloud_vswitch" "new" {
  vpc_id     = data.alicloud_vpcs.existing.vpcs[0].id   # 只引用不重建
  cidr_block = cidrsubnet(data.alicloud_vpcs.existing.vpcs[0].cidr_block, 8, 50)
  zone_id    = var.zone_a
}

locals {
  zones = slice(data.alicloud_zones.all.zones, 0, 3)    # 取前 3 个可用区
}
resource "alicloud_vswitch" "web" {
  for_each   = toset(local.zones)
  vpc_id     = alicloud_vpc.main.id
  zone_id    = each.key
  cidr_block = cidrsubnet(var.vpc_cidr, 8, index(local.zones, each.key))
}
resource "alicloud_instance" "web" {
  for_each        = toset(local.zones)
  image_id        = data.alicloud_images.alios.images[0].id   # 永远最新镜像
  vswitch_id      = alicloud_vswitch.web[each.key].id
  instance_type   = var.instance_type
  security_groups = [alicloud_security_group.web.id]
}

# —— AWS S3 + DynamoDB 锁（经典组合）——
terraform {
  backend "s3" {
    bucket         = "corp-tfstate-prod"
    key            = "infra-hq/terraform.tfstate"   # State 对象路径（按项目分层）
    region         = "ap-southeast-1"
    encrypt        = true                            # 服务端加密（State 含敏感值！）
    dynamodb_table = "terraform-locks"               # 锁表（预建，主键 LockID）
    # Terraform 1.10+ 的新机制：use_lockfile = true（改用 S3 对象锁，免 DynamoDB）
  }
}

# —— 阿里云 OSS + Tablestore 锁 ——
terraform {
  backend "oss" {
    bucket          = "corp-tfstate-prod"
    prefix          = "infra-hq"
    key             = "terraform.tfstate"
    region          = "cn-hangzhou"
    acl             = "private"
    tablestore      = "tf-lock"          # 预建 Tablestore 实例与表
    tablestore_table = "terraform-locks"
  }
}

# —— 腾讯云 COS ——
terraform {
  backend "cos" {
    bucket = "corp-tfstate-prod-1250000000"
    prefix = "infra-hq"
    key    = "terraform.tfstate"
    region = "ap-guangzhou"
    acl    = "private"
  }
}

# modules/vpc/outputs.tf —— 输出是模块对外的 API，命名即契约
output "vpc_id" {
  description = "VPC ID，供子模块引用"
  value       = alicloud_vpc.main.id
}
output "vswitch_ids" {
  description = "Web 子网 ID 列表（按可用区）"
  value       = { for k, v in alicloud_vswitch.web : k => v.id }
}

# 声明层：sensitive 的作用与边界
variable "db_password" {
  type      = string
  sensitive = true          # CLI/日志隐藏；State 明文（下一层防线管存储）
}
resource "alicloud_instance" "db" {
  password = var.db_password  # 值会写入 State（密码本身在云侧也有——这是平台行为）
}

# 注入层：Vault provider（apply 时从 Vault 取值，不写死）
data "vault_kv_secret_v2" "db" {
  mount = "secret"
  name  = "netops/db"
}
resource "alicloud_instance" "db" {
  password = data.vault_kv_secret_v2.db.data["password"]
}

# 环境变量注入（CI 主力通道）：
# export TF_VAR_db_password="$SECRET"    # 值来自 CI secret / 密管下发
